#[derive(Debug, Clone)]
#[allow(dead_code)]
enum JsonVal {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<JsonVal>),
    Obj(HashMap<String, JsonVal>),
}

impl JsonVal {
    fn get(&self, key: &str) -> Option<&Self> {
        match self {
            Self::Obj(m) => m.get(key),
            _ => None,
        }
    }

    fn as_f64(&self) -> Option<f64> {
        match self {
            Self::Num(n) => Some(*n),
            _ => None,
        }
    }

    fn as_u64(&self) -> Option<u64> {
        match self {
            Self::Num(n) if *n >= 0.0 => Some(*n as u64),
            _ => None,
        }
    }

    fn as_array(&self) -> Option<&[JsonVal]> {
        match self {
            Self::Arr(a) => Some(a.as_slice()),
            _ => None,
        }
    }
}

impl Index<&str> for JsonVal {
    type Output = JsonVal;
    fn index(&self, key: &str) -> &Self::Output {
        self.get(key).unwrap_or_else(|| panic!("missing json key `{key}`"))
    }
}

struct MiniJson<'a> {
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> MiniJson<'a> {
    fn skip_ws(&mut self) {
        while self.pos < self.bytes.len() && self.bytes[self.pos].is_ascii_whitespace() {
            self.pos += 1;
        }
    }

    fn parse_val(&mut self) -> JsonVal {
        self.skip_ws();
        match self.bytes[self.pos] {
            b'{' => self.parse_obj(),
            b'[' => self.parse_arr(),
            b'"' => JsonVal::Str(self.parse_str()),
            b't' => {
                self.pos += 4;
                JsonVal::Bool(true)
            }
            b'f' => {
                self.pos += 5;
                JsonVal::Bool(false)
            }
            b'n' => {
                self.pos += 4;
                JsonVal::Null
            }
            _ => self.parse_num(),
        }
    }

    fn parse_str(&mut self) -> String {
        assert_eq!(self.bytes[self.pos], b'"');
        self.pos += 1;
        let mut out = String::new();
        while self.pos < self.bytes.len() {
            let b = self.bytes[self.pos];
            self.pos += 1;
            if b == b'"' {
                return out;
            }
            if b == b'\\' {
                let esc = self.bytes[self.pos];
                self.pos += 1;
                match esc {
                    b'"' => out.push('"'),
                    b'\\' => out.push('\\'),
                    b'n' => out.push('\n'),
                    b'r' => out.push('\r'),
                    b't' => out.push('\t'),
                    other => out.push(other as char),
                }
            } else {
                out.push(b as char);
            }
        }
        panic!("unterminated json string");
    }

    fn parse_num(&mut self) -> JsonVal {
        let start = self.pos;
        while self.pos < self.bytes.len() {
            let b = self.bytes[self.pos];
            if b.is_ascii_digit() || matches!(b, b'-' | b'+' | b'.' | b'e' | b'E') {
                self.pos += 1;
            } else {
                break;
            }
        }
        let s = std::str::from_utf8(&self.bytes[start..self.pos]).unwrap();
        JsonVal::Num(s.parse::<f64>().unwrap_or_else(|e| panic!("bad json num `{s}`: {e}")))
    }

    fn parse_arr(&mut self) -> JsonVal {
        self.pos += 1;
        let mut items = Vec::new();
        loop {
            self.skip_ws();
            if self.bytes[self.pos] == b']' {
                self.pos += 1;
                return JsonVal::Arr(items);
            }
            items.push(self.parse_val());
            self.skip_ws();
            if self.bytes[self.pos] == b',' {
                self.pos += 1;
            }
        }
    }

    fn parse_obj(&mut self) -> JsonVal {
        self.pos += 1;
        let mut map = HashMap::new();
        loop {
            self.skip_ws();
            if self.bytes[self.pos] == b'}' {
                self.pos += 1;
                return JsonVal::Obj(map);
            }
            let key = self.parse_str();
            self.skip_ws();
            assert_eq!(self.bytes[self.pos], b':');
            self.pos += 1;
            let val = self.parse_val();
            map.insert(key, val);
            self.skip_ws();
            if self.bytes[self.pos] == b',' {
                self.pos += 1;
            }
        }
    }
}

fn load_oracles() -> JsonVal {
    let raw = include_str!("../reference/r23_fit_oracles.json");
    let mut p = MiniJson { bytes: raw.as_bytes(), pos: 0 };
    p.parse_val()
}

fn j_f64(v: &JsonVal, key: &str) -> f64 {
    v.get(key).and_then(JsonVal::as_f64).unwrap_or_else(|| panic!("missing f64 key `{key}` in {v:?}"))
}

fn j_vec(v: &JsonVal, key: &str) -> Vec<f64> {
    v.get(key)
        .and_then(JsonVal::as_array)
        .unwrap_or_else(|| panic!("missing array `{key}` in {v:?}"))
        .iter()
        .map(|x| x.as_f64().expect("numeric element"))
        .collect()
}

fn j_usize_vec(v: &JsonVal, key: &str) -> Vec<usize> {
    v.get(key)
        .and_then(JsonVal::as_array)
        .unwrap_or_else(|| panic!("missing usize array `{key}` in {v:?}"))
        .iter()
        .map(|x| x.as_u64().expect("integer element") as usize)
        .collect()
}

fn eps_vec(n: usize, amp: f64) -> Vec<f64> {
    (1..=n).map(|i| amp * (2.3 * (i as f64) + 0.7).sin()).collect()
}

fn assert_param_matches_oracle(
    res: &curvebook_fit::NonlinearFitResult,
    param_name: &str,
    oracle_params: &JsonVal,
    oracle_key: &str,
    rel_est: f64,
    rel_se: f64,
    ctx: &str,
) {
    let p = find_param(res, param_name);
    let op = &oracle_params[oracle_key];
    let est = j_f64(op, "est");
    let se = j_f64(op, "se");
    let lo = j_f64(op, "ci95_sym_lo");
    let hi = j_f64(op, "ci95_sym_hi");
    assert_approx_eq(p.estimate, est, 1e-6, rel_est, &format!("{ctx}.{param_name}.est"));
    assert_approx_eq(p.se, se, 1e-6, rel_se, &format!("{ctx}.{param_name}.se"));
    let (got_lo, got_hi) = unwrap_finite_ci((p.ci_lower, p.ci_upper), &format!("{ctx}.{param_name}.ci"));
    assert_approx_eq(got_lo, lo, 1e-5, rel_se.max(5e-3), &format!("{ctx}.{param_name}.ci_lo"));
    assert_approx_eq(got_hi, hi, 1e-5, rel_se.max(5e-3), &format!("{ctx}.{param_name}.ci_hi"));
}

fn find_derived_entry<'a>(res: &'a curvebook_fit::NonlinearFitResult, ds_idx: usize, name: &str) -> &'a curvebook_fit::DerivedScalar {
    res.derived_scalars[ds_idx]
        .iter()
        .find(|d| d.name.eq_ignore_ascii_case(name))
        .unwrap_or_else(|| panic!("missing derived scalar `{name}` on ds {ds_idx}: {:?}", res.derived_scalars[ds_idx]))
}

// ============================================================================
// 1. RELATIONAL INEQUALITY CONSTRAINTS
// ============================================================================

#[test]
fn r23_6_relational_constraints_oracles() {
    let root = load_oracles();
    let rel = &root["relational_constraints"];

    // 1A. Two-phase decay with KFast > KSlow (custom DSL matching R's Plateau + SpanFast*exp(-KFast*X) + SpanSlow*exp(-KSlow*X))
    let dec_direct = &rel["two_phase_decay_kfast_gt_kslow"]["direct"];
    let xs = j_vec(dec_direct, "x");
    let ys = j_vec(dec_direct, "y");
    let ds = series_xy(0, "Decay", &xs, &ys);
    let model = dsl_compile("Y = Plateau + SpanFast * exp(-KFast * X) + SpanSlow * exp(-KSlow * X)");

    let mut cfg = cfg_fast();
    cfg.parameter_rules = vec![
        rule_local_init("Plateau", 10.0),
        rule_local_bounds("SpanFast", Some(50.0), Some(0.0), None),
        rule_local_bounds("SpanSlow", Some(35.0), Some(0.0), None),
        rule_local_bounds("KFast", Some(1.5), Some(1e-6), None),
        rule_local_bounds("KSlow", Some(0.2), Some(1e-6), None),
    ];
    cfg.relational_constraints = vec![RelationalConstraint {
        lhs_param: "KFast".to_owned(),
        op: RelationalConstraintOp::GreaterThan,
        rhs_param: "KSlow".to_owned(),
        margin: 0.0,
    }];

    let fit = fit_with(&model, std::slice::from_ref(&ds), &cfg);
    assert_converged(&fit, "two_phase_decay KFast > KSlow");
    for p in ["Plateau", "SpanFast", "SpanSlow", "KFast", "KSlow"] {
        assert_param_matches_oracle(&fit, p, &dec_direct["params"], p, 1e-4, 2e-3, "two_phase_rel");
    }
    assert_approx_eq(
        find_param(&fit, "KFast").se,
        j_f64(&rel["two_phase_decay_kfast_gt_kslow"], "reparam_gap_se_kfast"),
        1e-6,
        2e-3,
        "reparam_gap_se_kfast",
    );
    assert_approx_eq(fit.rss, j_f64(dec_direct, "rss"), 1e-5, 1e-4, "two_phase_rel.rss");
    assert_approx_eq(fit.rmse, j_f64(dec_direct, "rmse"), 1e-5, 1e-4, "two_phase_rel.rmse");
    assert_approx_eq(fit.rsd, j_f64(dec_direct, "sy_x"), 1e-5, 1e-4, "two_phase_rel.sy_x");
    assert_approx_eq(fit.r_squared, j_f64(dec_direct, "r_squared"), 1e-6, 1e-6, "two_phase_rel.r2");
    assert_approx_eq(fit.adj_r_squared, j_f64(dec_direct, "adj_r_squared"), 1e-6, 1e-6, "two_phase_rel.adj_r2");

    // 1B. Active relational margin KFast >= KSlow + 2.0
    let dec_gap = &rel["two_phase_decay_kfast_gt_kslow"]["active_min_gap_2_0"];
    let mut cfg_gap = cfg.clone();
    cfg_gap.parameter_rules = vec![
        rule_local_init("Plateau", 10.0),
        rule_local_bounds("SpanFast", Some(50.0), Some(0.0), None),
        rule_local_bounds("SpanSlow", Some(35.0), Some(0.0), None),
        rule_local_bounds("KFast", Some(2.7), Some(1e-6), None),
        rule_local_bounds("KSlow", Some(0.2), Some(1e-6), None),
    ];
    cfg_gap.relational_constraints = vec![RelationalConstraint {
        lhs_param: "KFast".to_owned(),
        op: RelationalConstraintOp::GreaterOrEqual,
        rhs_param: "KSlow".to_owned(),
        margin: 2.0,
    }];
    let fit_gap = fit_with(&model, std::slice::from_ref(&ds), &cfg_gap);
    assert_converged(&fit_gap, "two_phase_decay KFast >= KSlow + 2.0");
    let kfast_g = param_val(&fit_gap, "KFast");
    let kslow_g = param_val(&fit_gap, "KSlow");
    assert!(kfast_g - kslow_g >= 2.0 - 1e-9, "active gap violated: KFast={kfast_g}, KSlow={kslow_g}");
    assert_approx_eq(kfast_g, j_f64(dec_gap, "kfast_constrained"), 1e-4, 5e-4, "active_gap.KFast");
    assert_approx_eq(kslow_g, j_f64(&dec_gap["params"]["KSlow"], "est"), 1e-4, 5e-4, "active_gap.KSlow");
    assert_approx_eq(param_val(&fit_gap, "Plateau"), j_f64(&dec_gap["params"]["Plateau"], "est"), 1e-3, 5e-4, "active_gap.Plateau");
    assert_approx_eq(fit_gap.rss, j_f64(dec_gap, "rss"), 1e-4, 5e-4, "active_gap.rss");
    assert_approx_eq(fit_gap.adj_r_squared, j_f64(dec_gap, "adj_r_squared"), 1e-5, 1e-5, "active_gap.adj_r2");

    // 1C. Two-site binding with KdLo > KdHi (even when initialized inverted, relational constraint orders KdLo > KdHi!)
    let bind = &rel["two_site_binding_kdlo_gt_kdhi"];
    let bx = j_vec(&bind["direct"], "x");
    let by = j_vec(&bind["direct"], "y");
    let bind_model = get_builtin_model("two_sites_specific_binding").unwrap();
    let mut cfg_bind = cfg_fast();
    cfg_bind.parameter_rules = vec![
        rule_local_bounds("BmaxHi", Some(40.0), Some(0.0), None),
        rule_local_bounds("BmaxLo", Some(90.0), Some(0.0), None),
        rule_local_bounds("KdHi", Some(0.5), Some(1e-6), None),
        rule_local_bounds("KdLo", Some(35.0), Some(1e-6), None),
    ];
    cfg_bind.relational_constraints = vec![RelationalConstraint {
        lhs_param: "KdLo".to_owned(),
        op: RelationalConstraintOp::GreaterThan,
        rhs_param: "KdHi".to_owned(),
        margin: 0.0,
    }];
    let fit_b = fit_with(bind_model.as_ref(), &[series_xy(0, "Bind", &bx, &by)], &cfg_bind);
    assert_converged(&fit_b, "two_site_binding KdLo > KdHi");
    assert!(param_val(&fit_b, "KdLo") > param_val(&fit_b, "KdHi"));
    assert_approx_eq(param_val(&fit_b, "KdLo"), j_f64(bind, "reparam_kdlo"), 1e-3, 1e-3, "bind.KdLo");
    assert_approx_eq(fit_b.rss, j_f64(bind, "reparam_rss"), 1e-4, 1e-4, "bind.rss");

    // 1D. Cyclic relational constraints must be rejected cleanly
    let mut cfg_cyc = cfg_fast();
    cfg_cyc.relational_constraints = vec![
        RelationalConstraint { lhs_param: "KFast".to_owned(), op: RelationalConstraintOp::GreaterThan, rhs_param: "KSlow".to_owned(), margin: 0.0 },
        RelationalConstraint { lhs_param: "KSlow".to_owned(), op: RelationalConstraintOp::GreaterThan, rhs_param: "KFast".to_owned(), margin: 0.0 },
    ];
    assert!(fit_nonlinear(&model, &[ds], &HookContext::default(), &cfg_cyc).is_err());
}

// ============================================================================
// 2. DERIVED-SCALAR CIs (MONOTONIC REVERSAL + DELTA METHOD + ROBUST SUPPRESSION)
// ============================================================================

#[test]
fn r23_6_derived_scalar_cis_and_robust_suppression() {
    let root = load_oracles();
    let dci = &root["derived_scalar_cis"];

    // 2A. 4PL EC50 (increasing monotonic CI) & Span (delta-method SE & CI)
    let o4 = &dci["four_pl_ec50_and_span"];
    let x4 = j_vec(&o4["fit"], "x");
    let y4 = j_vec(&o4["fit"], "y");
    let m4 = get_builtin_model("log_agonist_vs_response_4pl").unwrap();
    let fit4 = fit_with(m4.as_ref(), &[series_xy(0, "4PL", &x4, &y4)], &cfg_fast());
    assert_converged(&fit4, "4PL derived CI");
    let ec50 = find_derived_entry(&fit4, 0, "EC50");
    let ec50_ci = j_vec(o4, "ec50_monotonic_ci95");
    assert_approx_eq(ec50.value, j_f64(o4, "ec50_est"), 1e-10, 1e-4, "4PL.EC50.val");
    assert_approx_eq(ec50.se.unwrap(), j_f64(o4, "ec50_se_delta"), 1e-11, 2e-3, "4PL.EC50.se");
    assert_approx_eq(ec50.ci_lower.unwrap(), ec50_ci[0], 1e-10, 2e-3, "4PL.EC50.ci_lo");
    assert_approx_eq(ec50.ci_upper.unwrap(), ec50_ci[1], 1e-10, 2e-3, "4PL.EC50.ci_hi");

    let span4 = find_derived_entry(&fit4, 0, "Span");
    let span4_ci = j_vec(o4, "span_ci95_delta");
    assert_approx_eq(span4.value, j_f64(o4, "span_est"), 1e-4, 1e-4, "4PL.Span.val");
    assert_approx_eq(span4.se.unwrap(), j_f64(o4, "span_se_delta"), 1e-4, 2e-3, "4PL.Span.se");
    assert_approx_eq(span4.ci_lower.unwrap(), span4_ci[0], 1e-3, 1e-3, "4PL.Span.ci_lo");
    assert_approx_eq(span4.ci_upper.unwrap(), span4_ci[1], 1e-3, 1e-3, "4PL.Span.ci_hi");

    // 2B. Gaddum/Schild unity slope: KB = 10^(-pKB) decreasing -> exact bound reversal!
    let ogs = &dci["schild_unity_kb_bound_reversal"];
    let x_gs: Vec<f64> = (0..12).map(|i| -9.0 + 5.0 * (i as f64) / 11.0).collect();
    let antags = [0.0, 1e-7, 1e-6];
    let eps12 = eps_vec(12, 0.35);
    let gs_datasets: Vec<DatasetSeries> = antags
        .iter()
        .enumerate()
        .map(|(k, &b)| {
            let sign = if (k + 1) % 2 == 0 { -1.0 } else { 1.0 };
            let ys: Vec<f64> = x_gs
                .iter()
                .zip(&eps12)
                .map(|(&x, &e)| 5.0 + 95.0 / (1.0 + 10.0_f64.powf((-7.0 + (1.0 + b * 10.0_f64.powf(7.8)).log10() - x) * 1.2)) + sign * e)
                .collect();
            series_xy(k, &format!("B={b}"), &x_gs, &ys)
        })
        .collect();
    let m_gs = get_builtin_model("ec50_shift_gaddum_schild_unity_log").unwrap();
    let cfg_gs = cfg_fast_rules(vec![
        rule_shared("Bottom"),
        rule_shared("Top"),
        rule_shared("LogEC50"),
        rule_shared("HillSlope"),
        rule_shared("pKB"),
        rule_per_ds("AntagConc", &[(0, 0.0), (1, 1e-7), (2, 1e-6)]),
    ]);
    let fit_gs = fit_with(m_gs.as_ref(), &gs_datasets, &cfg_gs);
    assert_converged(&fit_gs, "Gaddum/Schild unity KB reversal");
    let kb = find_derived_entry(&fit_gs, 0, "KB");
    let kb_ci = j_vec(ogs, "kb_monotonic_ci95_reversed");
    assert!(kb.ci_lower.unwrap() < kb.value && kb.value < kb.ci_upper.unwrap(), "KB CI bounds must bracket estimate after reversal");
    assert_approx_eq(kb.value, j_f64(ogs, "kb_est"), 1e-11, 2e-4, "Schild.KB.val");
    assert_approx_eq(kb.se.unwrap(), j_f64(ogs, "kb_se_delta"), 1e-12, 5e-3, "Schild.KB.se");
    assert_approx_eq(kb.ci_lower.unwrap(), kb_ci[0], 1e-11, 5e-3, "Schild.KB.ci_lo");
    assert_approx_eq(kb.ci_upper.unwrap(), kb_ci[1], 1e-11, 5e-3, "Schild.KB.ci_hi");

    // 2C. One-Phase Decay: HalfLife = ln(2)/K (bound reversal) & Span = Y0 - Plateau (delta method)
    let o1p = &dci["one_phase_decay_halflife_and_span"];
    let x1p = j_vec(&o1p["fit"], "x");
    let y1p = j_vec(&o1p["fit"], "y");
    let m1p = get_builtin_model("one_phase_decay").unwrap();
    let fit1p = fit_with(m1p.as_ref(), &[series_xy(0, "1P", &x1p, &y1p)], &cfg_fast());
    assert_converged(&fit1p, "One-phase decay derived CI");
    let hl = find_derived_entry(&fit1p, 0, "HalfLife");
    let hl_ci = j_vec(o1p, "halflife_monotonic_ci95_reversed");
    assert_approx_eq(hl.value, j_f64(o1p, "halflife_est"), 1e-5, 2e-4, "1P.HalfLife.val");
    assert_approx_eq(hl.se.unwrap(), j_f64(o1p, "halflife_se_delta"), 1e-5, 2e-3, "1P.HalfLife.se");
    assert_approx_eq(hl.ci_lower.unwrap(), hl_ci[0], 1e-5, 2e-3, "1P.HalfLife.ci_lo");
    assert_approx_eq(hl.ci_upper.unwrap(), hl_ci[1], 1e-5, 2e-3, "1P.HalfLife.ci_hi");

    let sp1p = find_derived_entry(&fit1p, 0, "Span");
    let sp1p_ci = j_vec(o1p, "span_ci95_delta");
    assert_approx_eq(sp1p.value, j_f64(o1p, "span_est"), 1e-4, 2e-4, "1P.Span.val");
    assert_approx_eq(sp1p.se.unwrap(), j_f64(o1p, "span_se_delta"), 1e-4, 2e-3, "1P.Span.se");
    assert_approx_eq(sp1p.ci_lower.unwrap(), sp1p_ci[0], 1e-3, 2e-3, "1P.Span.ci_lo");
    assert_approx_eq(sp1p.ci_upper.unwrap(), sp1p_ci[1], 1e-3, 2e-3, "1P.Span.ci_hi");

    // 2D. R4.5: RobustCauchy must suppress SE & CI on all derived scalars while preserving point values
    let mut cfg_rob = cfg_fast();
    cfg_rob.method = FitMethod::RobustCauchy;
    let fit_rob = fit_with(m1p.as_ref(), &[series_xy(0, "1P_rob", &x1p, &y1p)], &cfg_rob);
    assert_converged(&fit_rob, "One-phase decay RobustCauchy");
    for d in &fit_rob.derived_scalars[0] {
        assert!(d.value.is_finite(), "RobustCauchy derived value `{}` should be finite", d.name);
        assert!(d.se.is_none(), "RobustCauchy must suppress SE on derived `{}`", d.name);
        assert!(d.ci_lower.is_none(), "RobustCauchy must suppress ci_lower on derived `{}`", d.name);
        assert!(d.ci_upper.is_none(), "RobustCauchy must suppress ci_upper on derived `{}`", d.name);
    }
}

// ============================================================================
// 3. ALL 8 FIXED CANONICAL BUILT-IN EQUATIONS
// ============================================================================

#[test]
fn r23_6_fixed_8_canonical_builtins_oracles() {
    let root = load_oracles();
    let f8 = &root["fixed_8_canonical_builtins"];

    // 3.1a operational_model_agonist (log-X, <A> full logistic vs <~A> partial operational)
    {
        let o = &f8["operational_model_agonist_log"];
        let xs = j_vec(o, "x");
        let ys = j_vec(o, "y");
        let dsi = j_usize_vec(o, "dataset_idx");
        let mut pts0 = Vec::new();
        let mut pts1 = Vec::new();
        for ((&x, &y), &d) in xs.iter().zip(&ys).zip(&dsi) {
            if d == 0 {
                pts0.push((x, y));
            } else {
                pts1.push((x, y));
            }
        }
        let ds0 = series_xy(0, "Full", &pts0.iter().map(|p| p.0).collect::<Vec<_>>(), &pts0.iter().map(|p| p.1).collect::<Vec<_>>());
        let ds1 = series_xy(1, "Partial", &pts1.iter().map(|p| p.0).collect::<Vec<_>>(), &pts1.iter().map(|p| p.1).collect::<Vec<_>>());
        let m = get_builtin_model("operational_model_agonist").unwrap();
        assert_grad_matches_fd(m.as_ref(), &[-6.5], &[4.0, 102.0, -7.2, -5.8, 0.15, 1.15], 0, 1e-5);
        assert_grad_matches_fd(m.as_ref(), &[-6.5], &[4.0, 102.0, -7.2, -5.8, 0.15, 1.15], 1, 1e-5);
        let fit = fit_with(m.as_ref(), &[ds0, ds1], &cfg_fast());
        assert_converged(&fit, "operational_model_agonist");
        assert_eq!(fit.df, 24, "unused <A>/<~A> slots must be omitted from free params (k=6, df=24)");
        for p in ["Basal", "EffectMax", "n"] {
            assert_param_matches_oracle(&fit, p, &o["params"], p, 5e-4, 5e-3, "op_log");
        }
        assert_approx_eq(find_param_ds(&fit, 0, "LogEC50").estimate, j_f64(&o["params"]["LogEC50"], "est"), 1e-4, 5e-4, "op_log.LogEC50");
        assert_approx_eq(find_param_ds(&fit, 1, "LogKA").estimate, j_f64(&o["params"]["LogKA"], "est"), 1e-4, 5e-4, "op_log.LogKA");
        assert_approx_eq(find_param_ds(&fit, 1, "LogTau").estimate, j_f64(&o["params"]["LogTau"], "est"), 1e-4, 5e-4, "op_log.LogTau");
        assert_approx_eq(fit.rss, j_f64(o, "rss"), 1e-4, 5e-4, "op_log.rss");
    }

    // 3.1b operational_model_agonist_conc (linear-X)
    {
        let o = &f8["operational_model_agonist_conc"];
        let xs = j_vec(o, "x");
        let ys = j_vec(o, "y");
        let dsi = j_usize_vec(o, "dataset_idx");
        let (mut x0, mut y0, mut x1, mut y1) = (Vec::new(), Vec::new(), Vec::new(), Vec::new());
        for ((&x, &y), &d) in xs.iter().zip(&ys).zip(&dsi) {
            if d == 0 {
                x0.push(x);
                y0.push(y);
            } else {
                x1.push(x);
                y1.push(y);
            }
        }
        let m = get_builtin_model("operational_model_agonist_conc").unwrap();
        assert_grad_matches_fd(m.as_ref(), &[1e-6], &[4.0, 102.0, 6e-8, 1.5e-6, 1.4, 1.15], 0, 1e-5);
        assert_grad_matches_fd(m.as_ref(), &[1e-6], &[4.0, 102.0, 6e-8, 1.5e-6, 1.4, 1.15], 1, 1e-5);
        let fit = fit_with(m.as_ref(), &[series_xy(0, "Full", &x0, &y0), series_xy(1, "Partial", &x1, &y1)], &cfg_fast());
        assert_converged(&fit, "operational_model_agonist_conc");
        assert_eq!(fit.df, 24);
        assert_approx_eq(find_param_ds(&fit, 0, "EC50").estimate, j_f64(&o["params"]["EC50"], "est"), 1e-10, 5e-4, "op_conc.EC50");
        assert_approx_eq(find_param_ds(&fit, 1, "KA").estimate, j_f64(&o["params"]["KA"], "est"), 1e-9, 5e-4, "op_conc.KA");
        assert_approx_eq(find_param_ds(&fit, 1, "Tau").estimate, j_f64(&o["params"]["Tau"], "est"), 1e-4, 5e-4, "op_conc.Tau");
        assert_approx_eq(fit.rss, j_f64(o, "rss"), 1e-4, 5e-4, "op_conc.rss");
    }

    // 3.2 log_agonist_vs_response_5pl parameterized directly in LogEC50
    {
        let o = &f8["log_agonist_vs_response_5pl_logec50"];
        let m = get_builtin_model("log_agonist_vs_response_5pl").unwrap();
        assert!(m.param_names().contains(&"LogEC50".to_owned()), "5PL must use LogEC50 directly");
        assert!(!m.param_names().contains(&"LogXb".to_owned()), "5PL must not expose LogXb as fitted param");
        let fit = fit_with(m.as_ref(), &[series_xy(0, "5PL", &j_vec(o, "x"), &j_vec(o, "y"))], &cfg_fast());
        assert_converged(&fit, "5PL LogEC50");
        for p in ["Bottom", "Top", "LogEC50", "HillSlope", "S"] {
            assert_param_matches_oracle(&fit, p, &o["params"], p, 5e-4, 5e-3, "5pl");
        }
        assert_approx_eq(fit.rss, j_f64(o, "rss"), 1e-4, 5e-4, "5pl.rss");
    }

    // 3.3 two_sites_fit_ki with separate HotKdNMHi and HotKdNMLo
    {
        let o = &f8["two_sites_fit_ki_dual_kd"];
        let m = get_builtin_model("two_sites_fit_ki").unwrap();
        let cfg = cfg_fast_rules(vec![
            rule_const("HotNM", j_f64(o, "HotNM")),
            rule_const("HotKdNMHi", j_f64(o, "HotKdNMHi")),
            rule_const("HotKdNMLo", j_f64(o, "HotKdNMLo")),
        ]);
        let fit = fit_with(m.as_ref(), &[series_xy(0, "2Ki", &j_vec(o, "x"), &j_vec(o, "y"))], &cfg);
        assert_converged(&fit, "two_sites_fit_ki");
        for p in ["Top", "Bottom", "FractionHi", "LogKiHi", "LogKiLo"] {
            assert_param_matches_oracle(&fit, p, &o["params"], p, 5e-4, 5e-3, "two_sites_fit_ki");
        }
        assert_approx_eq(fit.rss, j_f64(o, "rss"), 1e-4, 5e-4, "two_sites_fit_ki.rss");
    }

    // 3.4 association_kinetics_one_conc parameterized in Kon, Bmax (fixed Koff, Hotnm)
    {
        let o = &f8["association_kinetics_one_conc_kon_bmax"];
        let m = get_builtin_model("association_kinetics_one_conc").unwrap();
        assert_grad_matches_fd(m.as_ref(), &[12.0], &[8e6, 240.0, 0.05, 10.0], 0, 1e-5);
        let cfg = cfg_fast_rules(vec![rule_const("Koff", j_f64(o, "Koff")), rule_const("Hotnm", j_f64(o, "Hotnm"))]);
        let fit = fit_with(m.as_ref(), &[series_xy(0, "AK1", &j_vec(o, "x"), &j_vec(o, "y"))], &cfg);
        assert_converged(&fit, "association_kinetics_one_conc");
        for p in ["Kon", "Bmax"] {
            assert_param_matches_oracle(&fit, p, &o["params"], p, 5e-4, 5e-3, "ak1");
        }
        assert_approx_eq(find_derived(&fit, 0, "Kd"), j_f64(o, "derived_Kd"), 1e-12, 5e-4, "ak1.Kd");
        assert_approx_eq(find_derived(&fit, 0, "Kobs"), j_f64(o, "derived_Kobs"), 1e-5, 5e-4, "ak1.Kobs");
    }

    // 3.5 allosteric_ec50_shift (log-X) parameterized in LogKB, Logalpha
    {
        let o = &f8["allosteric_ec50_shift_logkb_logalpha"];
        let xs = j_vec(o, "x");
        let ys = j_vec(o, "y");
        let b_all = j_vec(o, "mod_conc");
        let mut datasets = Vec::new();
        for ds_idx in 0..3 {
            let start = ds_idx * 12;
            datasets.push(series_xy(ds_idx, &format!("B={}", b_all[start]), &xs[start..start + 12], &ys[start..start + 12]));
        }
        let m = get_builtin_model("allosteric_ec50_shift").unwrap();
        let cfg = cfg_fast_rules(vec![
            rule_shared("Bottom"),
            rule_shared("Top"),
            rule_shared("LogEC50"),
            rule_shared("HillSlope"),
            rule_shared("LogKB"),
            rule_shared("Logalpha"),
            rule_per_ds("ModConc", &[(0, b_all[0]), (1, b_all[12]), (2, b_all[24])]),
        ]);
        let fit = fit_with(m.as_ref(), &datasets, &cfg);
        assert_converged(&fit, "allosteric_ec50_shift");
        for p in ["Bottom", "Top", "LogEC50", "HillSlope", "LogKB", "Logalpha"] {
            assert_param_matches_oracle(&fit, p, &o["params"], p, 5e-4, 5e-3, "allo_shift");
        }
    }

    // 3.6 lorentzian parameterized in HWHM (Width = HWHM, derived FWHM = 2 * Width)
    {
        let o = &f8["lorentzian_hwhm"];
        let m = get_builtin_model("lorentzian").unwrap();
        assert_grad_matches_fd(m.as_ref(), &[5.0], &[42.0, 4.2, 1.8], 0, 1e-5);
        let fit = fit_with(m.as_ref(), &[series_xy(0, "Lor", &j_vec(o, "x"), &j_vec(o, "y"))], &cfg_fast());
        assert_converged(&fit, "lorentzian HWHM");
        for p in ["Amplitude", "Center", "Width"] {
            assert_param_matches_oracle(&fit, p, &o["params"], p, 5e-4, 5e-3, "lorentzian");
        }
        assert_approx_eq(find_derived(&fit, 0, "FWHM"), j_f64(o, "derived_fwhm"), 1e-4, 5e-4, "lorentzian.FWHM");
    }

    // 3.7 sine_wave, damped_sine_wave, sinc_wave parameterized in Wavelength
    {
        let os = &f8["sine_wave_wavelength"];
        let ms = get_builtin_model("sine_wave").unwrap();
        let cfg = cfg_fast_rules(vec![
            rule_local_init("Amplitude", 4.2),
            rule_local_bounds("Wavelength", Some(5.0), Some(1e-6), None),
            rule_local_init("PhaseShift", 0.5),
            rule_local_init("Baseline", 11.5),
        ]);
        let fit = fit_with(ms.as_ref(), &[series_xy(0, "Sine", &j_vec(os, "x"), &j_vec(os, "y"))], &cfg);
        assert_converged(&fit, "sine_wave Wavelength");
        for p in ["Amplitude", "Wavelength", "PhaseShift", "Baseline"] {
            assert_param_matches_oracle(&fit, p, &os["params"], p, 5e-4, 5e-3, "sine_wave");
        }
        assert_approx_eq(find_derived(&fit, 0, "Frequency"), j_f64(os, "derived_frequency"), 1e-5, 5e-4, "sine_wave.Frequency");

        let od = &f8["damped_sine_wave_wavelength"];
        let md = get_builtin_model("damped_sine_wave").unwrap();
        let cfg_d = cfg_fast_rules(vec![
            rule_local_init("Amplitude", 5.5),
            rule_local_bounds("K", Some(0.15), Some(0.0), None),
            rule_local_bounds("Wavelength", Some(4.2), Some(1e-6), None),
            rule_local_init("PhaseShift", 0.3),
        ]);
        let fit_d = fit_with(md.as_ref(), &[series_xy(0, "DSine", &j_vec(od, "x"), &j_vec(od, "y"))], &cfg_d);
        assert_converged(&fit_d, "damped_sine_wave Wavelength");
        for p in ["Amplitude", "K", "Wavelength", "PhaseShift"] {
            assert_param_matches_oracle(&fit_d, p, &od["params"], p, 5e-4, 5e-3, "damped_sine_wave");
        }
        assert_approx_eq(find_derived(&fit_d, 0, "Frequency"), j_f64(od, "derived_frequency"), 1e-5, 5e-4, "damped_sine_wave.Frequency");

        let oc = &f8["sinc_wave_wavelength"];
        let mc = get_builtin_model("sinc_wave").unwrap();
        let cfg_c = cfg_fast_rules(vec![rule_local_init("Amplitude", 14.0), rule_local_bounds("Wavelength", Some(4.5), Some(1e-6), None)]);
        let fit_c = fit_with(mc.as_ref(), &[series_xy(0, "Sinc", &j_vec(oc, "x"), &j_vec(oc, "y"))], &cfg_c);
        assert_converged(&fit_c, "sinc_wave Wavelength");
        for p in ["Amplitude", "Wavelength"] {
            assert_param_matches_oracle(&fit_c, p, &oc["params"], p, 5e-4, 5e-3, "sinc_wave");
        }
        assert_approx_eq(find_derived(&fit_c, 0, "Frequency"), j_f64(oc, "derived_frequency"), 1e-5, 5e-4, "sinc_wave.Frequency");
    }

    // 3.8 logistic_growth & gompertz_growth InflectionPoint + delta-method SE/CI
    for (id, key) in [("logistic_growth", "logistic_growth_inflection"), ("gompertz_growth", "gompertz_growth_inflection")] {
        let o = &f8[key];
        let m = get_builtin_model(id).unwrap();
        let fit = fit_with(m.as_ref(), &[series_xy(0, id, &j_vec(o, "x"), &j_vec(o, "y"))], &cfg_fast());
        assert_converged(&fit, id);
        for p in ["YM", "Y0", "k"] {
            assert_param_matches_oracle(&fit, p, &o["params"], p, 5e-4, 5e-3, id);
        }
        let inf = find_derived_entry(&fit, 0, "InflectionPoint");
        let inf_ci = j_vec(o, "x_inflect_ci95_delta");
        assert_approx_eq(inf.value, j_f64(o, "x_inflect_analytical"), 1e-4, 5e-4, &format!("{id}.InflectionPoint"));
        assert_approx_eq(inf.se.unwrap(), j_f64(o, "x_inflect_se_delta"), 1e-4, 5e-3, &format!("{id}.InflectionPoint.se"));
        assert_approx_eq(inf.ci_lower.unwrap(), inf_ci[0], 1e-3, 2e-3, &format!("{id}.InflectionPoint.ci_lo"));
        assert_approx_eq(inf.ci_upper.unwrap(), inf_ci[1], 1e-3, 2e-3, &format!("{id}.InflectionPoint.ci_hi"));
        assert_approx_eq(find_derived(&fit, 0, "YInflection"), j_f64(o, "y_inflect_analytical"), 1e-3, 5e-4, &format!("{id}.YInflection"));
        assert_approx_eq(find_derived(&fit, 0, "1/k"), j_f64(o, "inv_k"), 1e-4, 5e-4, &format!("{id}.inv_k"));
    }
}

// ============================================================================
// 4. ALL 7 NEW MODERN BUILT-IN EQUATIONS + 12 CLASSIC LEGACY REPARAMETERIZATIONS
// ============================================================================

#[test]
fn r23_6_new_7_modern_builtins_and_12_legacy_reparams() {
    let root = load_oracles();
    let m7 = &root["new_7_modern_builtins"];

    // 4.1 pade_1_1
    {
        let o = &m7["pade_1_1"];
        let m = get_builtin_model("pade_1_1").unwrap();
        assert_grad_matches_fd(m.as_ref(), &[3.0], &[2.5, 8.4, 0.42], 0, 1e-5);
        let fit = fit_with(m.as_ref(), &[series_xy(0, "Pade", &j_vec(o, "x"), &j_vec(o, "y"))], &cfg_fast());
        assert_converged(&fit, "pade_1_1");
        for p in ["A0", "A1", "B1"] {
            assert_param_matches_oracle(&fit, p, &o["params"], p, 5e-4, 5e-3, "pade_1_1");
        }
    }

    // 4.2 horizontal_line
    {
        let o = &m7["horizontal_line"];
        let m = get_builtin_model("horizontal_line").unwrap();
        assert_grad_matches_fd(m.as_ref(), &[5.0], &[18.5], 0, 1e-8);
        let fit = fit_with(m.as_ref(), &[series_xy(0, "Horiz", &j_vec(o, "x"), &j_vec(o, "y"))], &cfg_fast());
        assert_converged(&fit, "horizontal_line");
        assert_approx_eq(param_val(&fit, "Mean"), j_f64(o, "mean"), 1e-9, 1e-9, "horizontal_line.Mean");
        assert_approx_eq(find_param(&fit, "Mean").se, j_f64(o, "se"), 1e-9, 1e-9, "horizontal_line.SE");
        assert_approx_eq(fit.rss, j_f64(o, "rss"), 1e-9, 1e-9, "horizontal_line.rss");
        assert_approx_eq(fit.rmse, j_f64(o, "rmse"), 1e-9, 1e-9, "horizontal_line.rmse");
        assert_approx_eq(fit.rsd, j_f64(o, "sy_x"), 1e-9, 1e-9, "horizontal_line.sy_x");
    }

    // 4.3 semilog_x_lin_y_log
    {
        let o = &m7["semilog_x_lin_y_log"];
        let m = get_builtin_model("semilog_x_lin_y_log").unwrap();
        assert_grad_matches_fd(m.as_ref(), &[2.5], &[0.28, 0.45], 0, 1e-5);
        let fit = fit_with(m.as_ref(), &[series_xy(0, "SemilogY", &j_vec(o, "x"), &j_vec(o, "y"))], &cfg_fast());
        assert_converged(&fit, "semilog_x_lin_y_log");
        for p in ["Slope", "YIntercept"] {
            assert_param_matches_oracle(&fit, p, &o["params"], p, 5e-4, 5e-3, "semilog_x_lin_y_log");
        }
    }

    // 4.4 sum_of_two_lorentzians
    {
        let o = &m7["sum_of_two_lorentzians"];
        let m = get_builtin_model("sum_of_two_lorentzians").unwrap();
        assert_grad_matches_fd(m.as_ref(), &[9.0], &[30.0, 6.0, 1.4, 22.0, 13.5, 2.1], 0, 1e-5);
        let cfg = cfg_fast_rules(vec![
            rule_local_init("Amplitude1", 28.0),
            rule_local_init("Center1", 5.8),
            rule_local_bounds("Width1", Some(1.3), Some(1e-6), None),
            rule_local_init("Amplitude2", 20.0),
            rule_local_init("Center2", 13.2),
            rule_local_bounds("Width2", Some(2.0), Some(1e-6), None),
        ]);
        let fit = fit_with(m.as_ref(), &[series_xy(0, "2Lor", &j_vec(o, "x"), &j_vec(o, "y"))], &cfg);
        assert_converged(&fit, "sum_of_two_lorentzians");
        for p in ["Amplitude1", "Center1", "Width1", "Amplitude2", "Center2", "Width2"] {
            assert_param_matches_oracle(&fit, p, &o["params"], p, 5e-4, 5e-3, "sum_of_two_lorentzians");
        }
    }

    // 4.5-4.7 cumulative_gaussian_{percent, fraction, counts}
    for (id, params) in [
        ("cumulative_gaussian_percent", &["Mean", "SD"][..]),
        ("cumulative_gaussian_fraction", &["Mean", "SD"][..]),
        ("cumulative_gaussian_counts", &["N", "Mean", "SD"][..]),
    ] {
        let o = &m7[id];
        let m = get_builtin_model(id).unwrap();
        let fit = fit_with(m.as_ref(), &[series_xy(0, id, &j_vec(o, "x"), &j_vec(o, "y"))], &cfg_fast());
        assert_converged(&fit, id);
        for &p in params {
            assert_param_matches_oracle(&fit, p, &o["params"], p, 5e-4, 5e-3, id);
        }
    }

    // 5. Legacy reparameterizations (all 7 pinned JSON oracles + smoke recovery for remaining 5 + polynomial_1 alias)
    let leg = &root["legacy_reparameterizations"];
    for (id, param_pairs) in [
        ("classic_one_phase_decay", vec![("Span", "Span"), ("K", "K"), ("Plateau", "Plateau")]),
        ("classic_two_phase_decay", vec![("Span1", "Span1"), ("K1", "K1"), ("Span2", "Span2"), ("K2", "K2"), ("Plateau", "Plateau")]),
        ("classic_one_phase_association", vec![("Ymax", "Ymax"), ("K", "K")]),
        ("classic_two_phase_association", vec![("Ymax1", "Ymax1"), ("K1", "K1"), ("Ymax2", "Ymax2"), ("K2", "K2")]),
        ("classic_exponential_growth", vec![("Start", "Start"), ("K", "K")]),
        ("classic_one_site_binding", vec![("Bmax", "Bmax"), ("Kd", "Kd")]),
        ("classic_two_site_binding", vec![("Bmax1", "BmaxHi"), ("Kd1", "KdHi"), ("Bmax2", "BmaxLo"), ("Kd2", "KdLo")]),
    ] {
        let o = &leg[id];
        let m = get_builtin_model(id).unwrap();
        let fit = fit_with(m.as_ref(), &[series_xy(0, id, &j_vec(o, "x"), &j_vec(o, "y"))], &cfg_fast());
        assert_converged(&fit, id);
        for (model_p, oracle_p) in param_pairs {
            assert_param_matches_oracle(&fit, model_p, &o["params"], oracle_p, 1e-3, 1e-2, id);
        }
    }

    // Remaining 5 classic equations + polynomial_1 alias exact recovery on clean synthetic data
    assert_eq!(get_builtin_model("polynomial_1").unwrap().id(), "straight_line");
    for (id, xs, true_p) in [
        ("classic_sigmoidal_dose_response", vec![-9.0, -8.0, -7.5, -7.0, -6.5, -6.0, -5.0, -4.0], vec![5.0, 95.0, -6.5]),
        ("classic_sigmoidal_dose_response_variable_slope", vec![-9.0, -8.0, -7.5, -7.0, -6.5, -6.0, -5.0, -4.0], vec![5.0, 95.0, -6.5, 1.4]),
        ("classic_one_site_competition", vec![-9.0, -8.0, -7.5, -7.0, -6.5, -6.0, -5.0, -4.0], vec![10.0, 90.0, -6.8]),
        (
            "classic_two_site_competition",
            vec![-11.0, -10.0, -9.5, -9.0, -8.5, -8.0, -7.5, -7.0, -6.5, -6.0, -5.5, -5.0, -4.0, -3.0],
            vec![5.0, 100.0, 0.4, -8.8, -5.8],
        ),
        ("classic_sine_wave", (0..25).map(|i| 0.5 * (i as f64)).collect(), vec![4.0, 0.2, 0.5, 10.0]),
    ] {
        let m = get_builtin_model(id).unwrap();
        let ys: Vec<f64> = xs.iter().map(|&x| m.eval(&[x], &true_p, 0).unwrap()).collect();
        let rules: Vec<ParameterRule> = m.param_names().iter().zip(&true_p).map(|(n, &v)| rule_local_init(n, v * 0.9 + 0.05)).collect();
        let fit = fit_with(m.as_ref(), &[series_xy(0, id, &xs, &ys)], &cfg_fast_rules(rules));
        assert_converged(&fit, id);
        for (name, &truth) in m.param_names().iter().zip(&true_p) {
            assert_approx_eq(param_val(&fit, name), truth, 1e-4, 1e-4, &format!("{id}.{name}"));
        }
    }
}

// ============================================================================
// 5. GOF METRICS (ADJUSTED R^2, WEIGHTED R^2, RMSE) & POISSON NONLINEAR
// ============================================================================

#[test]
fn r23_6_gof_weighted_r2_and_poisson_nonlinear() {
    let root = load_oracles();
    let gof = &root["gof_and_poisson_nonlinear"];
    let leg_1b = &root["legacy_reparameterizations"]["classic_one_site_binding"];
    let x1b = j_vec(leg_1b, "x");
    let y1b = j_vec(leg_1b, "y");
    let m1b = get_builtin_model("classic_one_site_binding").unwrap();

    for (scheme, key) in [(WeightingScheme::RelativeSquare, "weighted_1_over_y2"), (WeightingScheme::Relative, "weighted_1_over_abs_y")] {
        let o = &gof[key];
        let mut cfg = cfg_fast();
        cfg.weighting = scheme;
        let fit = fit_with(m1b.as_ref(), &[series_xy(0, key, &x1b, &y1b)], &cfg);
        assert_converged(&fit, key);
        assert_approx_eq(param_val(&fit, "Bmax"), j_f64(&o["params"], "Bmax"), 1e-3, 1e-4, &format!("{key}.Bmax"));
        assert_approx_eq(param_val(&fit, "Kd"), j_f64(&o["params"], "Kd"), 1e-4, 1e-4, &format!("{key}.Kd"));
        assert_approx_eq(fit.weighted_ss, j_f64(o, "weighted_rss"), 1e-5, 5e-4, &format!("{key}.wrss"));
        assert_approx_eq(fit.weighted_r_squared.unwrap(), j_f64(o, "weighted_r2"), 1e-5, 1e-5, &format!("{key}.wr2"));
        assert_approx_eq(fit.weighted_adj_r_squared.unwrap(), j_f64(o, "weighted_adj_r2"), 1e-5, 1e-5, &format!("{key}.wadj_r2"));
        assert_approx_eq(fit.weighted_rmse.unwrap(), j_f64(o, "weighted_rmse"), 1e-5, 5e-4, &format!("{key}.wrmse"));
        assert_approx_eq(fit.weighted_sy_x.unwrap(), j_f64(o, "weighted_sy_x"), 1e-5, 5e-4, &format!("{key}.wsyx"));
        assert_approx_eq(fit.rmse, j_f64(o, "unweighted_rmse"), 1e-4, 5e-4, &format!("{key}.urmse"));
    }

    // End-to-end ResultSheet emits extra GOF rows when emit_extra_gof = true
    let sheet_w = xy_sheet_single("w_sheet", "Weighted", "Y", &x1b, &y1b);
    let mut nl_w = nl_fast("classic_one_site_binding");
    nl_w.weighting = WeightingScheme::RelativeSquare;
    nl_w.emit_extra_gof = true;
    let rs_w = exec_nl(&sheet_w, nl_w);
    assert!(tab_row(&rs_w, "nonlinear_gof", "Weighted R squared").len() == 1);
    assert!(tab_row(&rs_w, "nonlinear_gof", "Adjusted R squared").len() == 1);
    assert!(tab_row(&rs_w, "nonlinear_gof", "RMSE").len() == 1);
    assert_approx_eq(
        rs_w.lookup_scalar("WeightedR2", None).unwrap(),
        j_f64(&gof["weighted_1_over_y2"], "weighted_r2"),
        1e-5,
        1e-5,
        "ResultSheet.WeightedR2",
    );

    // Poisson nonlinear regression on Michaelis-Menten counts
    let op = &gof["poisson_nonlinear_mm"];
    let xp = j_vec(op, "x");
    let yp = j_vec(op, "y");
    let mm = get_builtin_model("michaelis_menten").unwrap();
    let mut cfg_p = cfg_fast();
    cfg_p.method = FitMethod::PoissonDeviance;
    let fit_p = fit_with(mm.as_ref(), &[series_xy(0, "Counts", &xp, &yp)], &cfg_p);
    assert_converged(&fit_p, "Poisson nonlinear MM");
    let se_f = j_vec(op, "se_fisher");
    assert_approx_eq(param_val(&fit_p, "Vmax"), j_f64(op, "vmax"), 1e-4, 1e-4, "poisson.Vmax");
    assert_approx_eq(param_val(&fit_p, "Km"), j_f64(op, "km"), 1e-4, 1e-4, "poisson.Km");
    assert_approx_eq(find_param(&fit_p, "Vmax").se, se_f[0], 1e-3, 1e-3, "poisson.Vmax.se");
    assert_approx_eq(find_param(&fit_p, "Km").se, se_f[1], 1e-3, 1e-3, "poisson.Km.se");

    let pg = fit_p.poisson_gof.as_ref().expect("poisson_gof populated under PoissonDeviance");
    assert_approx_eq(pg.nll, j_f64(op, "nll"), 1e-5, 1e-5, "poisson.nll");
    assert_approx_eq(pg.nll_saturated, j_f64(op, "nll_saturated"), 1e-5, 1e-5, "poisson.nll_sat");
    assert_approx_eq(pg.nll_null, j_f64(op, "nll_null"), 1e-5, 1e-5, "poisson.nll_null");
    assert_approx_eq(pg.deviance, j_f64(op, "deviance"), 1e-5, 1e-5, "poisson.deviance");
    assert_approx_eq(pg.null_deviance, j_f64(op, "null_deviance"), 1e-5, 1e-5, "poisson.null_deviance");
    assert_approx_eq(pg.pseudo_r2_deviance, j_f64(op, "pseudo_r2_deviance"), 1e-5, 1e-5, "poisson.pseudo_r2");
    assert_approx_eq(pg.pearson_chi2, j_f64(op, "pearson_chi2"), 1e-4, 1e-4, "poisson.pearson_chi2");
    assert_approx_eq(pg.dispersion, j_f64(op, "dispersion"), 1e-4, 1e-4, "poisson.dispersion");

    // End-to-end ResultSheet emits Poisson GOF rows & scalars
    let sheet_p = xy_sheet_single("p_sheet", "Poisson", "Counts", &xp, &yp);
    let mut nl_p = nl_fast("michaelis_menten");
    nl_p.method = FitMethod::PoissonDeviance;
    let rs_p = exec_nl(&sheet_p, nl_p);
    assert_approx_eq(rs_p.lookup_scalar("PoissonNLL", None).unwrap(), j_f64(op, "nll"), 1e-5, 1e-5, "rs.PoissonNLL");
    assert_approx_eq(rs_p.lookup_scalar("PoissonPseudoR2", None).unwrap(), j_f64(op, "pseudo_r2_deviance"), 1e-5, 1e-5, "rs.PoissonPseudoR2");
    assert_approx_eq(rs_p.lookup_scalar("PoissonDispersion", None).unwrap(), j_f64(op, "dispersion"), 1e-4, 1e-4, "rs.PoissonDispersion");
}

// ============================================================================
// 6. §6.2 CONTINUOUS & DISCRETE THEORETICAL DISTRIBUTION PLOTTING + HOOKS
// ============================================================================

#[test]
fn r23_6_section_6_2_distribution_plotting_and_hooks() {
    let root = load_oracles();
    let grids = &root["section_6_2_distribution_grids"];
    let hooks = HookContext::default();

    // 6A. Normal z two-tailed alpha = 0.05
    {
        let o = &grids["normal_z_two_tailed_005"];
        let cut = j_f64(o, "cutoff");
        let spec = TheoreticalDistributionSpec {
            family: TheoreticalDistributionFamily::Normal,
            parameters: vec![0.0, 1.0],
            parameter_hooks: Vec::new(),
            tail_shade: DistributionTailShade::TwoTailed { lower: -cut, upper: cut },
            cumulative: false,
        };
        let plot = evaluate_theoretical_distribution(&spec, &hooks, Some(-4.0), Some(4.0), 16).unwrap();
        assert_eq!(plot.shaded_regions.len(), 2);
        assert_eq!(plot.overlays.len(), 3);
        let ox = j_vec(o, "x");
        let opdf = j_vec(o, "pdf");
        let oleft = j_vec(o, "left_tail_y");
        let oright = j_vec(o, "right_tail_y");
        for i in 0..ox.len() {
            assert_approx_eq(plot.x[i], ox[i], 1e-12, 1e-12, "z.x");
            assert_approx_eq(plot.y[i], opdf[i], 1e-12, 1e-12, "z.pdf");
            assert_approx_eq(plot.shaded_regions[0].y[i], oleft[i], 1e-12, 1e-12, "z.left_tail");
            assert_approx_eq(plot.shaded_regions[1].y[i], oright[i], 1e-12, 1e-12, "z.right_tail");
        }
        assert_approx_eq(plot.shaded_regions[0].area + plot.shaded_regions[1].area, 0.05, 1e-9, 1e-9, "z.two_tailed_area");
    }

    // 6B. Student t df=12 two-tailed alpha = 0.05
    {
        let o = &grids["student_t_df12_two_tailed_005"];
        let cut = j_f64(o, "cutoff");
        let spec = TheoreticalDistributionSpec {
            family: TheoreticalDistributionFamily::StudentT,
            parameters: vec![j_f64(o, "df")],
            parameter_hooks: Vec::new(),
            tail_shade: DistributionTailShade::TwoTailed { lower: -cut, upper: cut },
            cumulative: false,
        };
        let plot = evaluate_theoretical_distribution(&spec, &hooks, Some(-4.0), Some(4.0), 16).unwrap();
        for (i, ((&op, &ol), &or)) in j_vec(o, "pdf").iter().zip(&j_vec(o, "left_tail_y")).zip(&j_vec(o, "right_tail_y")).enumerate() {
            assert_approx_eq(plot.y[i], op, 1e-11, 1e-11, "t.pdf");
            assert_approx_eq(plot.shaded_regions[0].y[i], ol, 1e-11, 1e-11, "t.left_tail");
            assert_approx_eq(plot.shaded_regions[1].y[i], or, 1e-11, 1e-11, "t.right_tail");
        }
    }

    // 6C. Fisher-Snedecor F(4, 20) upper tail alpha = 0.05
    {
        let o = &grids["snedecor_f_4_20_upper_005"];
        let cut = j_f64(o, "cutoff");
        let spec = TheoreticalDistributionSpec {
            family: TheoreticalDistributionFamily::FisherF,
            parameters: vec![j_f64(o, "df1"), j_f64(o, "df2")],
            parameter_hooks: Vec::new(),
            tail_shade: DistributionTailShade::UpperTail { cutoff: cut },
            cumulative: false,
        };
        let plot = evaluate_theoretical_distribution(&spec, &hooks, Some(0.0), Some(6.0), 12).unwrap();
        for (i, (&op, &ou)) in j_vec(o, "pdf").iter().zip(&j_vec(o, "upper_tail_y")).enumerate() {
            assert_approx_eq(plot.y[i], op, 1e-11, 1e-11, "f.pdf");
            assert_approx_eq(plot.shaded_regions[0].y[i], ou, 1e-11, 1e-11, "f.upper_tail");
        }
    }

    // 6D. Chi-square df=5 upper tail alpha = 0.05
    {
        let o = &grids["chi_square_df5_upper_005"];
        let cut = j_f64(o, "cutoff");
        let spec = TheoreticalDistributionSpec {
            family: TheoreticalDistributionFamily::ChiSquare,
            parameters: vec![j_f64(o, "df")],
            parameter_hooks: Vec::new(),
            tail_shade: DistributionTailShade::UpperTail { cutoff: cut },
            cumulative: false,
        };
        let plot = evaluate_theoretical_distribution(&spec, &hooks, Some(0.0), Some(18.0), 12).unwrap();
        for (i, (&op, &ou)) in j_vec(o, "pdf").iter().zip(&j_vec(o, "upper_tail_y")).enumerate() {
            assert_approx_eq(plot.y[i], op, 1e-11, 1e-11, "chi2.pdf");
            assert_approx_eq(plot.shaded_regions[0].y[i], ou, 1e-11, 1e-11, "chi2.upper_tail");
        }
    }

    // 6E. Discrete Binomial(n=12, p=0.35)
    {
        let o = &grids["binomial_n12_p035"];
        let spec = TheoreticalDistributionSpec {
            family: TheoreticalDistributionFamily::Binomial,
            parameters: vec![j_f64(o, "n"), j_f64(o, "p")],
            parameter_hooks: Vec::new(),
            tail_shade: DistributionTailShade::None,
            cumulative: false,
        };
        let plot = evaluate_theoretical_distribution(&spec, &hooks, None, None, 64).unwrap();
        assert!(plot.is_discrete);
        for (i, ((&opmf, &ocdf), &osf)) in j_vec(o, "pmf").iter().zip(&j_vec(o, "cdf_le")).zip(&j_vec(o, "sf_ge")).enumerate() {
            assert_approx_eq(plot.x[i], i as f64, 1e-12, 1e-12, "binom.k");
            assert_approx_eq(plot.y[i], opmf, 1e-12, 1e-12, "binom.pmf");
            assert_approx_eq(plot.cdf_le[i], ocdf, 1e-12, 1e-12, "binom.cdf_le");
            assert_approx_eq(plot.sf_ge[i], osf, 1e-12, 1e-12, "binom.sf_ge");
        }
    }

    // 6F. Discrete Poisson(lambda=4.2) + HookedConstant via execute_nonlinear_analysis on empty sheet
    {
        let o = &grids["poisson_lambda4_2"];
        let mut info = InfoSheet::new_preseeded(SheetId::new("info-1"), "Params").unwrap();
        info.set_constant("RateLambda", ConstantValue::Number(j_f64(o, "lambda")), None).unwrap();
        let hook_ctx = HookContext { info_sheets: &[info], primary_info_sheet_id: Some(&SheetId::new("info-1")), ..HookContext::default() };

        let dist_spec = TheoreticalDistributionSpec {
            family: TheoreticalDistributionFamily::Poisson,
            parameters: vec![1.0], // overridden by hook!
            parameter_hooks: vec![Some(HookSource::InfoConstant { info_sheet_id: None, constant_name: "RateLambda".to_owned() })],
            tail_shade: DistributionTailShade::None,
            cumulative: false,
        };
        let plot = evaluate_theoretical_distribution(&dist_spec, &hook_ctx, Some(0.0), Some(14.0), 64).unwrap();
        assert_approx_eq(plot.resolved_parameters[0], 4.2, 1e-12, 1e-12, "poisson.hooked_lambda");
        for (i, ((&opmf, &ocdf), &osf)) in j_vec(o, "pmf").iter().zip(&j_vec(o, "cdf_le")).zip(&j_vec(o, "sf_ge")).enumerate() {
            assert_approx_eq(plot.y[i], opmf, 1e-12, 1e-12, "pois.pmf");
            assert_approx_eq(plot.cdf_le[i], ocdf, 1e-12, 1e-12, "pois.cdf_le");
            assert_approx_eq(plot.sf_ge[i], osf, 1e-12, 1e-12, "pois.sf_ge");
        }

        // Execute end-to-end through execute_analysis with an empty XY sheet!
        let empty_sheet = xy_sheet_single("empty", "Empty", "Y", &[], &[]);
        let mut nl = nl_fast("plot_distribution");
        nl.plot_distribution = Some(dist_spec);
        nl.plot_x_min = Some(0.0);
        nl.plot_x_max = Some(14.0);
        let rs = exec_nl_hooks(&empty_sheet, nl, &hook_ctx);
        assert_eq!(rs.fitted_curves.len(), 1);
        assert_eq!(rs.fitted_curves[0].points.len(), 15);
        assert_approx_eq(rs.lookup_scalar("Lambda", Some(0)).unwrap(), 4.2, 1e-12, 1e-12, "rs.dist.Lambda");
        let analyzable = rs.analyzable_data.as_ref().expect("analyzable_data emitted");
        analyzable.validate().expect("analyzable_data sheet passes validation");

        // Discrete Between shading includes both integer endpoints: P(2 <= X <= 5) == sum_{k=2}^5 PMF(k).
        let binom_between = TheoreticalDistributionSpec {
            family: TheoreticalDistributionFamily::Binomial,
            parameters: vec![12.0, 0.35],
            parameter_hooks: Vec::new(),
            tail_shade: DistributionTailShade::Between { lower: 2.0, upper: 5.0 },
            cumulative: false,
        };
        let b_plot = evaluate_theoretical_distribution(&binom_between, &hooks, None, None, 64).unwrap();
        let pmf_sum: f64 = b_plot.shaded_regions[0].y.iter().sum();
        assert_approx_eq(b_plot.shaded_regions[0].area, pmf_sum, 1e-12, 1e-12, "binomial Between includes lower endpoint");
    }
}

// ============================================================================
// 7. CUSTOM DSL: [Constraints], Y[expr]/X[expr] IN [Transforms], SYNTAX & ALIASES
// ============================================================================

#[test]
fn r23_6_dsl_constraints_transforms_and_syntax() {
    // 7A. [Constraints] section: fixed constant, bounds, shared global, relational, mandatory constant
    let src_rel = "\
        [Equation]\n\
        Y = Plateau + SpanFast * exp(-KFast * X) + SpanSlow * exp(-KSlow * X)\n\
        [Constraints]\n\
        0 <= SpanFast <= 200\n\
        SpanSlow must be greater than 0\n\
        KFast >= KSlow + 0.5\n\
        KSlow > 0\n\
        Plateau = 10.0\n\
    ";
    let m_rel = dsl_compile(src_rel);
    assert_eq!(m_rel.default_relational_constraints().len(), 1);
    assert_eq!(m_rel.default_relational_constraints()[0].lhs_param, "KFast");
    assert_eq!(m_rel.default_relational_constraints()[0].rhs_param, "KSlow");
    assert_approx_eq(m_rel.default_relational_constraints()[0].margin, 0.5, 1e-12, 1e-12, "dsl.margin");
    let xs: Vec<f64> = (0..15).map(|i| 0.5 * (i as f64)).collect();
    let ys: Vec<f64> = xs.iter().map(|&x| 10.0 + 40.0 * (-1.5 * x).exp() + 25.0 * (-0.3 * x).exp()).collect();
    let fit_rel = fit_with(&m_rel, &[series_xy(0, "DSL", &xs, &ys)], &cfg_fast());
    assert_converged(&fit_rel, "DSL [Constraints]");
    assert!(param_val(&fit_rel, "KFast") >= param_val(&fit_rel, "KSlow") + 0.5 - 1e-9);
    assert_approx_eq(param_val(&fit_rel, "KFast"), 1.5, 1e-3, 1e-3, "dsl.KFast");
    assert_approx_eq(param_val(&fit_rel, "KSlow"), 0.3, 1e-3, 1e-3, "dsl.KSlow");

    // Mandatory constant prompt (`HotNM = ?`) rejects fit until user supplies constant rule
    let src_mand = "\
        [Equation]\n\
        Y = Bmax * X / (Kd * (1 + HotNM) + X)\n\
        [Constraints]\n\
        HotNM = ?\n\
        Bmax > 0\n\
        Kd > 0\n\
    ";
    let m_mand = dsl_compile(src_mand);
    assert_eq!(m_mand.mandatory_constant_params(), vec!["HotNM".to_owned()]);
    let ds_mand = series_xy(0, "M", &[1.0, 2.0, 5.0, 10.0, 20.0], &[20.0, 33.33, 55.56, 71.43, 83.33]);
    assert!(fit_nonlinear(&m_mand, std::slice::from_ref(&ds_mand), &HookContext::default(), &cfg_fast()).is_err());
    let fit_mand_ok = fit_with(&m_mand, &[ds_mand], &cfg_fast_rules(vec![rule_const("HotNM", 1.0)]));
    assert_converged(&fit_mand_ok, "DSL mandatory constant bound");

    // Reject unknown param, infeasible bounds, and cyclic relational constraints in [Constraints]
    assert_dsl_compile_err("Y = A * X\n[Constraints]\nNoSuchParam > 0");
    assert_dsl_compile_err("Y = A * X\n[Constraints]\nA > 10\nA < 5");
    assert_dsl_compile_err("Y = A * X + B\n[Constraints]\nA > B\nB > A");

    // 7B. [Transforms] with Y[expr] and X[expr] (including derived SE/CI propagation!)
    let src_tr = "\
        [Equation]\n\
        Y = Bottom + (Top - Bottom) / (1 + 10^(LogEC50 - X))\n\
        [Transforms]\n\
        Y_at_m6 = Y[-6]\n\
        X_at_mid = X[0.5 * (Top + Bottom)]\n\
        X_at_75 = X[Bottom + 0.75 * (Top - Bottom)]\n\
    ";
    let m_tr = dsl_compile(src_tr);
    let x_tr: Vec<f64> = (-9..=-3).map(|v| v as f64).collect();
    let y_tr: Vec<f64> =
        x_tr.iter().enumerate().map(|(i, &x)| 10.0 + 90.0 / (1.0 + 10.0_f64.powf(-6.2 - x)) + 0.1 * ((i as f64) * 1.7).sin()).collect();
    let fit_tr = fit_with(&m_tr, &[series_xy(0, "TR", &x_tr, &y_tr)], &cfg_fast());
    assert_converged(&fit_tr, "DSL Y[expr] / X[expr]");
    let x_mid = find_derived_entry(&fit_tr, 0, "X_at_mid");
    let log_ec50 = param_val(&fit_tr, "LogEC50");
    assert_approx_eq(x_mid.value, log_ec50, 1e-6, 1e-6, "X[mid] == LogEC50");
    assert!(x_mid.se.is_some_and(|s| s.is_finite() && s > 0.0), "X[mid] must propagate delta SE");
    assert!(x_mid.ci_lower.is_some() && x_mid.ci_upper.is_some(), "X[mid] must propagate CI");
    let y_m6 = find_derived_entry(&fit_tr, 0, "Y_at_m6");
    let expected_ym6 = m_tr.eval(&[-6.0], &fit_tr.datasets[0].params, 0).unwrap();
    assert_approx_eq(y_m6.value, expected_ym6, 1e-10, 1e-10, "Y[-6]");
    assert_approx_eq(find_derived(&fit_tr, 0, "X_at_75"), log_ec50 + 3.0_f64.log10(), 1e-6, 1e-6, "X[75%] == LogEC50 + log10(3)");
    // Y[expr]/X[expr] disallowed in [Equation]
    assert_dsl_compile_err("Y = Y[X] + 1");
    assert_dsl_compile_err("Y = X[1] + A");

    // 7C. Syntax extensions: Y', Y[0], [] / {} grouping, \ continuation, stepped <A:J,3> & multi-letter <AA>, variadic AND/OR, infix AND/OR, prefix NOT
    let m_ode = dsl_compile("Y[0] = A0\nY' = -k * Y");
    assert_eq!(m_ode.kind(), DslEquationKind::OdeFirstOrder);
    assert_approx_eq(m_ode.eval(&[2.0], &[0.5, 100.0], 0).unwrap(), 100.0 * (-1.0_f64).exp(), 1e-8, 1e-8, "Y' + Y[0]");

    let m_grp = dsl_compile("Y = {[A + B] * \\\n    (X + 1)}");
    assert_approx_eq(m_grp.eval(&[3.0], &[2.0, 5.0], 0).unwrap(), 28.0, 1e-12, 1e-12, "[]/{}/backslash");
    assert_dsl_compile_err("Y = (X + 1]");
    assert_dsl_compile_err("Y = {X + 1)");

    let m_step = dsl_compile("<A:J,3> Y = 10\n<~A:J,3> Y = IF(AND(X > 0, X < 10, X != 5), 1, IF(OR(X == 5, X == 20, X == 30), 2, 0))\n<AA> Y = 26");
    for ds_idx in [0, 3, 6, 9] {
        assert_eq!(m_step.eval(&[1.0], &[], ds_idx), Some(10.0), "stepped <A:J,3> ds={ds_idx}");
    }
    assert_eq!(m_step.eval(&[1.0], &[], 26), Some(26.0), "multi-letter <AA> -> ds=26");
    assert_eq!(m_step.eval(&[4.0], &[], 1), Some(1.0), "variadic AND true");
    assert_eq!(m_step.eval(&[5.0], &[], 1), Some(2.0), "variadic OR true");
    assert_eq!(m_step.eval(&[50.0], &[], 1), Some(0.0), "variadic AND/OR false");

    let m_logic = dsl_compile("Y = IF(X > 0 AND X < 5 OR NOT (X < 10), 1, 0)");
    assert_eq!(m_logic.eval(&[3.0], &[], 0), Some(1.0));
    assert_eq!(m_logic.eval(&[7.0], &[], 0), Some(0.0));
    assert_eq!(m_logic.eval(&[12.0], &[], 0), Some(1.0));

    // 7D. Missing aliases & 2-arg round wired to curvebook_math::special
    let alias_cases: &[(&str, f64, f64)] = &[
        ("Y = arccos(0.5)", 0.5_f64.acos(), 1e-14),
        ("Y = arcsin(0.5)", 0.5_f64.asin(), 1e-14),
        ("Y = arccosh(2.0)", 2.0_f64.acosh(), 1e-14),
        ("Y = arcsinh(1.5)", 1.5_f64.asinh(), 1e-14),
        ("Y = arctanh(0.5)", 0.5_f64.atanh(), 1e-14),
        ("Y = arctan2(1.0, 2.0)", 1.0_f64.atan2(2.0), 1e-14),
        ("Y = besselj(2, 3.0)", curvebook_math::special::bessel_j(2, 3.0).unwrap(), 1e-12),
        ("Y = bessely(2, 3.0)", curvebook_math::special::bessel_y(2, 3.0).unwrap(), 1e-12),
        ("Y = besseli(2, 3.0)", curvebook_math::special::bessel_i(2, 3.0).unwrap(), 1e-12),
        ("Y = besselk(2, 1.5)", curvebook_math::special::bessel_k(2, 1.5).unwrap(), 1e-12),
        ("Y = hyp1f1(1.5, 2.5, 1.2)", curvebook_math::special::hyp1f1(1.5, 2.5, 1.2).unwrap(), 1e-11),
        ("Y = hyp2f1(0.5, 1.5, 2.5, 0.3)", curvebook_math::special::hyp2f1(0.5, 1.5, 2.5, 0.3).unwrap(), 1e-11),
        ("Y = confluent_u(1.5, 2.5, 1.2)", curvebook_math::special::confluent_u(1.5, 2.5, 1.2).unwrap(), 1e-10),
        ("Y = igamma(2.5, 1.5)", curvebook_math::special::igamma(2.5, 1.5).unwrap(), 1e-13),
        ("Y = igammac(2.5, 1.5)", curvebook_math::special::igammac(2.5, 1.5).unwrap(), 1e-13),
        ("Y = ibeta(2.0, 3.0, 0.4)", curvebook_math::special::ibeta(0.4, 2.0, 3.0).unwrap(), 1e-13),
        ("Y = digamma(3.5)", curvebook_math::special::digamma(3.5).unwrap(), 1e-13),
        ("Y = round(2.45678, 2)", 2.46, 1e-12),
        ("Y = round(1234.5, -2)", 1200.0, 1e-12),
        ("Y = round(2.6)", 3.0, 1e-12),
    ];
    for &(src, expected, tol) in alias_cases {
        let m = dsl_compile(src);
        let got = m.eval(&[0.0], &[], 0).unwrap_or_else(|| panic!("eval None for `{src}`"));
        assert_approx_eq(got, expected, tol, tol, src);
    }
}

// ============================================================================
// 8. MULTIPLE VARIABLES UNKNOWN INTERPOLATION
// ============================================================================

#[test]
fn r23_6_multivar_unknown_interpolation() {
    // 2 groups ("G1": Y = 2*X + 1; "G2": Y = 3*X + 5), each with (blank X, finite Y) and (finite X, blank Y) unknown rows!
    let mut mv = MultipleVariablesTable::new(3, 12).unwrap();
    mv.variables[0].title = "Group".to_owned();
    mv.variables[0].lock_role(VariableRole::Categorical);
    mv.variables[1].title = "X".to_owned();
    mv.variables[1].lock_role(VariableRole::Continuous);
    mv.variables[2].title = "Y".to_owned();
    mv.variables[2].lock_role(VariableRole::Continuous);

    let rows: [(&str, Option<f64>, Option<f64>); 12] = [
        ("G1", Some(0.0), Some(1.0)),
        ("G1", Some(1.0), Some(3.0)),
        ("G1", Some(2.0), Some(5.0)),
        ("G1", Some(4.0), Some(9.0)),
        ("G1", None, Some(7.0)), // unknown X -> should interpolate X = 3.0
        ("G1", Some(5.0), None), // unknown Y -> should interpolate Y = 11.0
        ("G2", Some(0.0), Some(5.0)),
        ("G2", Some(1.0), Some(8.0)),
        ("G2", Some(2.0), Some(11.0)),
        ("G2", Some(4.0), Some(17.0)),
        ("G2", None, Some(14.0)), // unknown X -> should interpolate X = 3.0
        ("G2", Some(5.0), None),  // unknown Y -> should interpolate Y = 20.0
    ];
    for (r, &(grp, x_opt, y_opt)) in rows.iter().enumerate() {
        mv.variables[0].cells[r] = Cell::text(grp);
        mv.variables[1].cells[r] = x_opt.map_or_else(Cell::empty, Cell::number);
        mv.variables[2].cells[r] = y_opt.map_or_else(Cell::empty, Cell::number);
    }
    let sheet = DataSheet::new(SheetId::new("mv-unk"), "MV Unknowns", TableArchetype::MultipleVariables(mv)).unwrap();

    // Direct extraction check
    let extracted = extract_datasets_from_sheet_multi(&sheet, &[], &[0], &[1], &[2]).unwrap();
    assert_eq!(extracted.len(), 2);
    assert_eq!(extracted[0].points.len(), 4);
    assert_eq!(extracted[0].unknowns_y.len(), 1);
    assert_eq!(extracted[0].unknowns_x.len(), 1);
    assert_eq!(extracted[1].unknowns_y.len(), 1);
    assert_eq!(extracted[1].unknowns_x.len(), 1);

    // End-to-end execution with interpolate_unknowns = true
    let mut nl = nl_fast("straight_line");
    nl.mv_group_columns = vec![0];
    nl.mv_x_columns = vec![1];
    nl.mv_y_column = Some(2);
    nl.interpolate_unknowns = true;
    let rs = exec_nl(&sheet, nl);
    let interp_tab = rs.tabs.iter().find(|t| t.id == "nonlinear_interpolated").expect("interpolated tab emitted");
    assert_eq!(interp_tab.rows.len(), 4, "2 unknown X + 2 unknown Y rows across both groups");
    // Check solved values via fit_nonlinear directly as well
    let model = get_builtin_model("straight_line").unwrap();
    let mut cfg = cfg_fast();
    cfg.interpolate_unknowns = true;
    let fit = fit_with(model.as_ref(), &extracted, &cfg);
    assert_eq!(fit.interpolated_x.len(), 2);
    assert_eq!(fit.interpolated_y.len(), 2);
    assert_approx_eq(fit.interpolated_x[0].output_estimate, 3.0, 1e-6, 1e-6, "G1 X from Y=7");
    assert_approx_eq(fit.interpolated_y[0].output_estimate, 11.0, 1e-6, 1e-6, "G1 Y from X=5");
    assert_approx_eq(fit.interpolated_x[1].output_estimate, 3.0, 1e-6, 1e-6, "G2 X from Y=14");
    assert_approx_eq(fit.interpolated_y[1].output_estimate, 20.0, 1e-6, 1e-6, "G2 Y from X=5");
}

// ============================================================================
// 9. PROPTEST EDGE-CASE INVARIANTS (n=0,1, ACTIVE BOUNDARY, DEGENERATE, NaN/Inf)
// ============================================================================

proptest! {
    #![proptest_config(ProptestConfig::with_cases(32))]

    #[test]
    fn prop_r23_6_edge_cases_never_panic(
        n_tiny in 0_usize..=1,
        x0 in prop::num::f64::ANY,
        y0 in prop::num::f64::ANY,
        margin in 0.0_f64..10.0,
    ) {
        // 1. n = 0 or n = 1 (including NaN/Inf) never panics on built-in & DSL models
        let model = get_builtin_model("one_phase_decay").unwrap();
        let pts: Vec<DataPoint> = if n_tiny == 0 { Vec::new() } else { vec![DataPoint::xy(x0, y0)] };
        let ds = DatasetSeries {
            data_set_index: 0,
            label: "Tiny".to_owned(),
            points: pts,
            unknowns_y: Vec::new(),
            unknowns_x: Vec::new(),
            is_pre_summarized: false,
            column_title_value: None,
        };
        let _ = fit_nonlinear(model.as_ref(), &[ds], &HookContext::default(), &cfg_fast());

        // 2. Active relational constraint boundary always respected when converged
        let m_rel = dsl_compile("Y = A * exp(-K1 * X) + B * exp(-K2 * X)");
        let xs: [f64; 8] = [0.0, 1.0, 2.0, 3.0, 4.0, 6.0, 8.0, 10.0];
        let ys: Vec<f64> = xs.iter().map(|&x| 50.0 * (-0.8 * x).exp() + 30.0 * (-0.4 * x).exp()).collect();
        let mut cfg = cfg_fast();
        cfg.parameter_rules = vec![
            rule_local_bounds("A", Some(50.0), Some(0.0), None),
            rule_local_bounds("B", Some(30.0), Some(0.0), None),
            rule_local_bounds("K1", Some(0.5 + margin), Some(1e-4), None),
            rule_local_bounds("K2", Some(0.4), Some(1e-4), None),
        ];
        cfg.relational_constraints = vec![RelationalConstraint {
            lhs_param: "K1".to_owned(),
            op: RelationalConstraintOp::GreaterOrEqual,
            rhs_param: "K2".to_owned(),
            margin,
        }];
        if let Ok(fit) = fit_nonlinear(&m_rel, &[series_xy(0, "R", &xs, &ys)], &HookContext::default(), &cfg)
            && matches!(fit.status, FitStatus::Converged | FitStatus::Ambiguous)
        {
            let k1 = param_val(&fit, "K1");
            let k2 = param_val(&fit, "K2");
            prop_assert!(k1 - k2 >= margin - 1e-6, "relational gap violated: k1={k1}, k2={k2}, margin={margin}");
        }

        // 3. Degenerate / collinear model (Y = (A + B) * X) never panics
        let m_col = dsl_compile("Y = (A + B) * X");
        let ds_col = series_xy(0, "Col", &[0.0, 1.0, 2.0, 3.0, 4.0], &[0.0, 2.0, 4.0, 6.0, 8.0]);
        let _ = fit_nonlinear(&m_col, &[ds_col], &HookContext::default(), &cfg_fast());

        // 4. NaN / Inf inputs to theoretical distribution evaluator never panic
        let dist_spec = TheoreticalDistributionSpec {
            family: TheoreticalDistributionFamily::Normal,
            parameters: vec![x0, y0],
            parameter_hooks: Vec::new(),
            tail_shade: DistributionTailShade::LowerTail { cutoff: x0 },
            cumulative: false,
        };
        let _ = evaluate_theoretical_distribution(&dist_spec, &HookContext::default(), Some(x0), Some(y0), 16);
    }
}

// ============================================================================
// 10. TARGETED REGRESSION TESTS FOR VERIFIER FINDINGS (#31)
// ============================================================================

#[test]
fn r23_6_regression_distribution_overflow_and_sheet_id_truncation() {
    let hooks = HookContext::default();

    // 1. Poisson u64 overflow & huge discrete bounds / cutoffs never panic or loop
    let pois = TheoreticalDistributionSpec {
        family: TheoreticalDistributionFamily::Poisson,
        parameters: vec![4.2],
        parameter_hooks: Vec::new(),
        tail_shade: DistributionTailShade::None,
        cumulative: false,
    };
    assert!(evaluate_theoretical_distribution(&pois, &hooks, None, Some(1e30), 64).is_err());
    assert!(evaluate_theoretical_distribution(&pois, &hooks, Some(1e30), Some(1e31), 64).is_err());
    assert!(evaluate_theoretical_distribution(&pois, &hooks, Some(0.0), Some(-1.0), 64).is_err());

    let pois_huge_lambda = TheoreticalDistributionSpec {
        family: TheoreticalDistributionFamily::Poisson,
        parameters: vec![1e30],
        parameter_hooks: Vec::new(),
        tail_shade: DistributionTailShade::None,
        cumulative: false,
    };
    assert!(evaluate_theoretical_distribution(&pois_huge_lambda, &hooks, None, None, 64).is_err());

    let binom = TheoreticalDistributionSpec {
        family: TheoreticalDistributionFamily::Binomial,
        parameters: vec![12.0, 0.35],
        parameter_hooks: Vec::new(),
        tail_shade: DistributionTailShade::None,
        cumulative: false,
    };
    assert!(evaluate_theoretical_distribution(&binom, &hooks, None, Some(1e30), 64).is_err());
    assert!(evaluate_theoretical_distribution(&binom, &hooks, Some(1e30), Some(1e31), 64).is_err());

    let pois_huge_lower = TheoreticalDistributionSpec {
        family: TheoreticalDistributionFamily::Poisson,
        parameters: vec![4.2],
        parameter_hooks: Vec::new(),
        tail_shade: DistributionTailShade::LowerTail { cutoff: 1e30 },
        cumulative: false,
    };
    let p_lo = evaluate_theoretical_distribution(&pois_huge_lower, &hooks, Some(0.0), Some(14.0), 64).unwrap();
    assert_approx_eq(p_lo.shaded_regions[0].area, 1.0, 1e-12, 1e-12, "poisson huge lower cutoff cdf==1");

    let pois_huge_upper = TheoreticalDistributionSpec {
        family: TheoreticalDistributionFamily::Poisson,
        parameters: vec![4.2],
        parameter_hooks: Vec::new(),
        tail_shade: DistributionTailShade::UpperTail { cutoff: 1e30 },
        cumulative: false,
    };
    let p_hi = evaluate_theoretical_distribution(&pois_huge_upper, &hooks, Some(0.0), Some(14.0), 64).unwrap();
    assert_approx_eq(p_hi.shaded_regions[0].area, 0.0, 1e-12, 1e-12, "poisson huge upper cutoff sf==0");

    // 2. Continuous range/span overflow rejected cleanly without NaN grids
    let norm_huge_sd = TheoreticalDistributionSpec {
        family: TheoreticalDistributionFamily::Normal,
        parameters: vec![0.0, 1e308],
        parameter_hooks: Vec::new(),
        tail_shade: DistributionTailShade::None,
        cumulative: false,
    };
    assert!(evaluate_theoretical_distribution(&norm_huge_sd, &hooks, None, None, 32).is_err());

    let norm_std = TheoreticalDistributionSpec {
        family: TheoreticalDistributionFamily::Normal,
        parameters: vec![0.0, 1.0],
        parameter_hooks: Vec::new(),
        tail_shade: DistributionTailShade::None,
        cumulative: false,
    };
    assert!(evaluate_theoretical_distribution(&norm_std, &hooks, Some(-1e308), Some(1e308), 32).is_err());
    let wide_ok = evaluate_theoretical_distribution(&norm_std, &hooks, Some(-1e307), Some(1e307), 16).unwrap();
    assert!(wide_ok.x.iter().all(|v| v.is_finite()), "wide finite span must not overflow intermediate x");

    // 3. Long ResultSheet IDs near/at MAX_SHEET_ID_BYTES (ASCII & multi-byte UTF-8) still emit valid analyzable_data
    let empty_sheet = xy_sheet_single("empty", "Empty", "Y", &[], &[]);
    let long_ascii_id = "a".repeat(curvebook_doc::error::MAX_SHEET_ID_BYTES);
    // 124 two-byte UTF-8 chars ('é' = 2 bytes -> 248 bytes) + 3 bytes ('x' + 'é') crosses byte 250 mid-codepoint!
    let long_utf8_id = format!("{}xéé", "é".repeat(124));
    assert!(long_utf8_id.len() <= curvebook_doc::error::MAX_SHEET_ID_BYTES);
    assert!(long_utf8_id.len() > curvebook_doc::error::MAX_SHEET_ID_BYTES - 6);
    for raw_id in [long_ascii_id, long_utf8_id] {
        let mut nl = nl_fast("plot_distribution");
        nl.plot_distribution = Some(norm_std.clone());
        let spec = AnalysisSpec::new(raw_id, empty_sheet.id.clone(), AnalysisKind::NonlinearRegression(nl)).unwrap();
        let rs = execute_analysis(&spec, &empty_sheet, &hooks).unwrap();
        let analyzable = rs.analyzable_data.as_ref().expect("analyzable_data must not be silently dropped");
        assert!(analyzable.id.as_str().len() <= curvebook_doc::error::MAX_SHEET_ID_BYTES);
        assert!(analyzable.id.as_str().ends_with("_curve"));
        analyzable.validate().expect("truncated derived sheet must pass validation");
    }
}

#[test]
fn r23_6_regression_disparate_scale_derived_scalar_and_prose_whitespace() {
    // 4. Disparate parameter scales (Kon ~ 1e9, Koff ~ 1e-4) in Kd = Koff / Kon must retain BOTH
    // parameter variances and their covariance in the delta-method SE instead of dropping Kon.
    let src_kin = "\
        [Equation]\n\
        Y = Bmax * (Kon * 1e-13 / (Kon * 1e-13 + Koff)) * (1 - exp(-(Kon * 1e-13 + Koff) * X)) + Bmax * 0.5 * (Kon * 5e-13 / (Kon * 5e-13 + Koff)) * (1 - exp(-(Kon * 5e-13 + Koff) * X))\n\
        [Transforms]\n\
        Kd = Koff / Kon\n\
    ";
    let m_kin = dsl_compile(src_kin);
    let p_names = m_kin.param_names();
    let idx_bmax = p_names.iter().position(|n| n == "Bmax").unwrap();
    let idx_kon = p_names.iter().position(|n| n == "Kon").unwrap();
    let idx_koff = p_names.iter().position(|n| n == "Koff").unwrap();
    let mut p_true = vec![0.0; p_names.len()];
    p_true[idx_bmax] = 100.0;
    p_true[idx_kon] = 1.0e9;
    p_true[idx_koff] = 1.0e-4;

    let xs: Vec<f64> = (1..=24).map(|i| (i as f64) * 500.0).collect();
    let ys: Vec<f64> = xs.iter().enumerate().map(|(i, &x)| m_kin.eval(&[x], &p_true, 0).unwrap() + 0.35 * ((i as f64) * 2.1).sin()).collect();
    let mut cfg = cfg_fast();
    cfg.parameter_rules = vec![
        rule_local_bounds("Bmax", Some(98.0), Some(1.0), None),
        rule_local_bounds("Kon", Some(1.05e9), Some(1e6), None),
        rule_local_bounds("Koff", Some(9.5e-5), Some(1e-7), None),
    ];
    let fit = fit_with(&m_kin, &[series_xy(0, "Kin", &xs, &ys)], &cfg);
    assert_converged(&fit, "disparate-scale Kd = Koff / Kon");

    let kon_hat = param_val(&fit, "Kon");
    let koff_hat = param_val(&fit, "Koff");
    let slot_kon = fit.parameters.iter().position(|p| p.name == "Kon").unwrap();
    let slot_koff = fit.parameters.iter().position(|p| p.name == "Koff").unwrap();
    let d_kd_dkon = -koff_hat / (kon_hat * kon_hat);
    let d_kd_dkoff = 1.0 / kon_hat;
    // Confirm ratio of raw gradients is indeed far below 1e-12 (~1e-13)
    assert!((d_kd_dkon / d_kd_dkoff).abs() < 1e-12, "test fixture must exercise disparate gradient ratio < 1e-12");

    let cov = &fit.covariance.covariance_matrix;
    let var_full = d_kd_dkon * d_kd_dkon * cov[slot_kon][slot_kon]
        + d_kd_dkoff * d_kd_dkoff * cov[slot_koff][slot_koff]
        + 2.0 * d_kd_dkon * d_kd_dkoff * cov[slot_kon][slot_koff];
    let se_full = var_full.sqrt();
    let se_koff_only = d_kd_dkoff.abs() * cov[slot_koff][slot_koff].sqrt();
    // Ensure the 2-parameter SE is measurably distinct from the 1-parameter Koff-only SE
    assert!((se_full - se_koff_only).abs() / se_full > 1e-2, "fixture should distinguish full delta SE from 1-param SE");

    let kd_entry = find_derived_entry(&fit, 0, "Kd");
    assert_approx_eq(kd_entry.value, koff_hat / kon_hat, 1e-12, 1e-18, "Kd value");
    let got_se = kd_entry.se.expect("Kd must have delta-method SE");
    assert_approx_eq(got_se, se_full, 1e-3, 1e-18, "Kd SE must include Kon variance & covariance");
    assert!(kd_entry.ci_lower.is_some() && kd_entry.ci_upper.is_some());

    // 5. Prose [Constraints] with extra whitespace around operators and keywords
    let src_ws = "\
        [Equation]\n\
        Y = A * exp(-KFast * X) + B * exp(-KSlow * X)\n\
        [Constraints]\n\
        KFast   must   be   greater   than   KSlow  +  0.5\n\
        A   must   be   greater   than   or   equal   to   0\n\
        B   must   be   less   than   or   equal   to   100\n\
    ";
    let m_ws = dsl_compile(src_ws);
    let rels = m_ws.default_relational_constraints();
    assert_eq!(rels.len(), 1);
    assert_eq!(rels[0].lhs_param, "KFast");
    assert_eq!(rels[0].rhs_param, "KSlow");
    assert_eq!(rels[0].op, RelationalConstraintOp::GreaterThan);
    assert_approx_eq(rels[0].margin, 0.5, 1e-12, 1e-12, "prose whitespace margin");
    let rules = m_ws.default_parameter_rules(&[]);
    assert!(rules.iter().any(|r| r.name == "A" && r.lower_bound == Some(0.0)));
    assert!(rules.iter().any(|r| r.name == "B" && r.upper_bound == Some(100.0)));
}
